import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawn,spawnSync} from 'node:child_process';
import * as m from '../scripts/mutagate.mjs';
import {inputFiles} from '../scripts/inputs.cjs';
import {tomlConfig,bridgeSource} from '../scripts/mutmut-bridge.cjs';
function fixture(t, config={}) {const repo=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'mutagate-')));t.after(()=>fs.rmSync(repo,{recursive:true,force:true}));const put=(f,s)=>{fs.mkdirSync(path.dirname(path.join(repo,f)),{recursive:true});fs.writeFileSync(path.join(repo,f),s);};put('src/main/java/acme/Foo.java','package acme; public class Foo { public int price(int n) { return n >= 5 ? 10 : 20; }}');put('src/test/java/acme/FooTest.java','package acme; public class FooTest {}');put('build.gradle',"plugins { id 'java' }");const root=path.join(repo,'.cache'),data=path.join(root,'repos',m.hash(repo));const c={repo,root,data,session:'test',sid:'test',harness:'claude',args:{},config:{...structuredClone(m.DEFAULTS),...config},errors:[],stateFile:path.join(data,'state/test.json')};return {c,put,test:'src/test/java/acme/FooTest.java',source:'src/main/java/acme/Foo.java'};}
const raw=(status='SURVIVED',line=1)=>[{file:'Foo.java',class:'acme.Foo',line,method:'price',mutator:'CONDITIONALS_BOUNDARY',description:'changed conditional boundary',status}];
test('clipped retry invalidates a prior error and stays pending',async t=>{const {c,test:file}=fixture(t,{gateBudgetSec:1});await m.register(c,file);const key=m.hash('acme.Foo');await m.runTarget(c,key,async()=>{throw Error('runner failed (1): missing JDK');});const before=m.state(c).targets[key].lastRunMs;let calls=0;const g=await m.gate(c,{hook:true,runner:async()=>{calls++;throw Error('runner failed (SIGKILL)');}});assert.equal(g.code,1);assert.equal(g.block,true);assert.match(g.reason,/results pending/);assert.equal(calls,1);assert.equal(m.loadResult(c,key,m.state(c).targets[key]),null);assert.ok(m.state(c).targets[key].lastRunMs>=before);});
async function scored(t,status='SURVIVED',config={}) {const f=fixture(t,config);await m.register(f.c,f.test);f.key=m.hash('acme.Foo');await m.runTarget(f.c,f.key,async()=>({raw:raw(status)}));return f;}
test('default globs and custom test matching',()=>{for(const f of ['src/test/java/A.java','FooTests.kt','x/test_foo.py','x/foo_test.py','src/foo.spec.ts','__tests__/foo.js'])assert.equal(m.isTest(f),true,f);for(const f of ['tests/conftest.py','tests/__init__.py','tests/test_x.py'])assert.equal(m.isTest(f),true,f);assert.equal(m.isTest('src/main/java/Foo.java'),false);assert.equal(m.isTest('foo.spec.ts',{...m.DEFAULTS,testGlobs:['checks/**']}),false);});
test('patch extracts adds, edits, removals and moves without executing text',()=>assert.deepEqual(m.extractPaths({tool_name:'apply_patch',tool_input:{command:'*** Begin Patch\n*** Add File: a.test.ts\n*** Update File: a.ts\n*** Move to: b.ts\n*** Delete File: c.ts\n*** End Patch'}}),['a.test.ts','a.ts','b.ts','c.ts']));
test('path confinement rejects traversal and symlink escape',t=>{const {c}=fixture(t);assert.equal(m.safePath(c.repo,'../outside'),null);fs.symlinkSync(os.tmpdir(),path.join(c.repo,'escape'),'dir');assert.equal(m.safePath(c.repo,'escape/file'),null);assert.equal(m.safePath(c.repo,'new/file'),path.join(c.repo,'new/file'));});
test('configuration precedence, type checks and safe defaults',t=>{const {c,put}=fixture(t);put('.mutagate/config.json','{"threshold":0.6}');assert.equal(m.configFor(c.repo,c.root,{threshold:'0.9'},{MUTAGATE_THRESHOLD:'0.7'}).config.threshold,.9);assert.equal(m.configFor(c.repo,c.root,{},{}).config.threshold,.6);assert.equal(m.configFor(c.repo,c.root,{threshold:'2'},{}).config.threshold,.8);});
test('target selection resolves package and ambiguous explicit selection',async t=>{const f=fixture(t);assert.equal(m.resolveTargets(f.c,f.test).targets[0].target,'acme.Foo');f.put('src/main/kotlin/acme/Foo.kt','package acme\nclass Foo');assert.equal(m.resolveTargets(f.c,f.test).ambiguous,true);const r=await m.register(f.c,f.test,'src/main/java/acme/Foo.java');assert.equal(r.targets.length,1);assert.equal(m.resolveTargets(f.c,f.test).targets.length,1);});
test('Kotlin PIT targets include the file facade, honoring JvmName, and its continuations are filtered',t=>{const {c,put}=fixture(t);const kt=src=>{put('src/main/kotlin/acme/Foo.kt',src);return m.pitTargets(c,{target:'acme.Foo',language:'kotlin',file:'src/main/kotlin/acme/Foo.kt'});};assert.equal(m.pitTargets(c,{target:'acme.Foo',language:'java',file:'src/main/java/acme/Foo.java'}),'acme.Foo,acme.Foo$*');assert.equal(kt('package acme\nclass Foo\nprivate fun x() = 1'),'acme.Foo,acme.Foo$*,acme.FooKt,acme.FooKt$*');assert.equal(kt('@file:JvmName("Tools")\npackage acme\nclass Foo'),'acme.Foo,acme.Foo$*,acme.Tools,acme.Tools$*');assert.equal(m.junkRule({file:'src/main/kotlin/acme/Foo.kt',class:'acme.FooKt$load$1',method:'invokeSuspend',line:0},[],'package acme\nsuspend fun load() = 1')?.id,'source-continuation');});
test('PIT parser preserves escaped descriptions and CSV handles quoting',()=>{assert.equal(m.parsePitXML('<mutations><mutation status="SURVIVED"><sourceFile>Foo.kt</sourceFile><mutatedClass>a.Foo</mutatedClass><mutatedMethod>x</mutatedMethod><lineNumber>42</lineNumber><mutator>MATH</mutator><description>a &gt; b &amp; c</description></mutation></mutations>')[0].description,'a > b & c');assert.deepEqual(m.parseCSV('a,"b,c","a""b"\r\n'),[['a','b,c','a"b']]);});
test('score counts timeouts, coverage, errors and zero eligible mutants',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],rr=m.normalize([...raw('KILLED'),...raw('TIMED_OUT',2),...raw('NO_COVERAGE',3),...raw('RUN_ERROR',4)],f.c,target);assert.equal(rr.score,2/3);assert.equal(rr.timed_out,1);assert.equal(rr.no_coverage,1);assert.equal(rr.error_mutants,1);assert.equal(m.normalize([],f.c,target).status,'unscored');f.c.config.countNoCoverage=false;assert.equal(m.normalize([...raw('KILLED'),...raw('NO_COVERAGE',3)],f.c,target).score,1);});
test('Kotlin filter does not discard Java or arbitrary suspend logic',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0];let r=m.normalize([{...raw()[0],file:'Foo.kt',method:'foo$default'}, {...raw()[0],file:'Foo.java',method:'foo$default'}, {...raw()[0],file:'Foo.kt',method:'invokeSuspend'}],f.c,target);assert.equal(r.filtered_junk,1);assert.equal(r.survived,2);});
test('report cap is 1800 characters, factual and ranked',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],r=m.normalize(Array.from({length:100},(_,n)=>({...raw()[0],line:n+1,description:'long factual description '.repeat(20)})),f.c,target);const text=m.report(r);assert.ok(text.length<=1800);assert.match(text,/survivors shown of 100/);assert.match(text,/Playbook:/);});
test('report collapses identical survivor lines and states the no-weakening rule',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],r=m.normalize([...[1,2,3,4].map(k=>({...raw('NO_COVERAGE',36)[0],mutation_key:String(k)})),...raw('SURVIVED',7)],f.c,target);const text=m.report(r),lines=text.split('\n').filter(l=>l.startsWith('src/'));assert.equal(lines.length,2,text);assert.ok(lines.some(l=>l.endsWith(' ×4')),text);assert.match(text,/5 survivors shown of 5/);assert.match(text,/don't weaken reachable code/);});
test('passing report has no footer and joined reports state the rule once, last, within the cap',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],rule=/^Kill survivors/,count=s=>s.split('\n').filter(l=>rule.test(l)).length;assert.doesNotMatch(m.report(m.normalize(raw('KILLED'),f.c,target)),/Kill survivors/);const one=m.report(m.normalize(raw(),f.c,target)),long=m.report(m.normalize(Array.from({length:100},(_,n)=>({...raw()[0],line:n+1,description:'long factual description '.repeat(20)})),f.c,target));for(const [text,max] of [[m.joinReports([one,one]),Infinity],[m.joinReports([long,long,long],1800),1800]]){assert.ok(text.length<=max);assert.equal(count(text),1,text);assert.match(text.split('\n').at(-1),rule);}assert.doesNotMatch(m.joinReports([m.report(m.normalize(raw('KILLED'),f.c,target)),'x']),/Kill survivors/);});
test('gate with two below-threshold targets states the rule once, last, in report and reason',async t=>{const f=fixture(t);for(const n of ['Foo','Bar']){f.put(`src/main/java/acme/${n}.java`,`package acme; public class ${n} {}`);f.put(`src/test/java/acme/${n}Test.java`,`package acme; public class ${n}Test {}`);await m.register(f.c,`src/test/java/acme/${n}Test.java`);}for(const n of ['Foo','Bar'])await m.runTarget(f.c,m.hash('acme.'+n),async()=>({raw:raw().map(x=>({...x,file:n+'.java',class:'acme.'+n}))}));const g=await m.gate(f.c,{hook:true});for(const text of [g.report,g.reason]){assert.match(text,/acme\.Bar score/);assert.match(text,/acme\.Foo score/);assert.equal(text.split('\n').filter(l=>/^Kill survivors/.test(l)).length,1,text);assert.match(text.split('\n').at(-1),/^Kill survivors/);}});
test('gate CLI report is not cut off before a below-threshold target listed last',async t=>{const f=fixture(t),long=Array.from({length:10},(_,n)=>({...raw('SURVIVED',n+1)[0],method:'longMethodName'.repeat(20)})),killed=Array.from({length:50},(_,n)=>raw('KILLED',n+20)[0]);for(const n of ['A','B','Bar']){f.put(`src/main/java/acme/${n}.java`,`package acme; public class ${n} {}`);f.put(`src/test/java/acme/${n}Test.java`,`package acme; public class ${n}Test {}`);await m.register(f.c,`src/test/java/acme/${n}Test.java`);}for(const n of ['A','B','Bar'])await m.runTarget(f.c,m.hash('acme.'+n),async()=>({raw:n==='Bar'?raw():[...long,...killed]}));const text=(await m.gate(f.c)).report;assert.match(text,/mutagate: acme\.A score 0\.83/);assert.match(text,/mutagate: acme\.Bar score 0\.00/);});
test('unresolved warnings for deleted test files are dropped from status and gate',async t=>{const f=await scored(t),gone='mutagate: target unresolved for src/test/java/acme/GoneTest.java. Candidates: none. Select with mutagate run src/test/java/acme/GoneTest.java --target <target>.',kept=`mutagate: target unresolved for ${f.test}. Candidates: none. Select with mutagate run ${f.test} --target <target>.`;await m.updateState(f.c,s=>{s.warnings=[gone,kept];});for(const text of [m.status(f.c),(await m.gate(f.c)).report]){assert.ok(!text.includes('GoneTest'),text);assert.ok(text.includes(kept),text);}});
test('low quality blocks twice, including stop_hook_active, then warns',async t=>{const {c}=await scored(t);for(let n=0;n<2;n++){const r=await m.handleHook(c,{stop_hook_active:true},'Stop');assert.equal(r.code,2);assert.equal(r.out.decision,'block');}const r=await m.handleHook(c,{},'Stop');assert.equal(r.code,0);assert.match(r.out.systemMessage,/round cap/);assert.equal((await m.gate(c)).code,1);});
test('pass allows and infrastructure errors fail open',async t=>{const f=await scored(t,'KILLED');assert.equal((await m.handleHook(f.c,{},'Stop')).code,0);f.put(f.source,'changed');const jdk=async()=>{throw Error('missing JDK');};await m.runTarget(f.c,f.key,jdk);await m.runTarget(f.c,f.key,jdk);const r=await m.handleHook(f.c,{},'Stop');assert.equal(r.code,0);assert.match(r.out.systemMessage,/missing JDK/);});
test('advise mode never blocks',async t=>{const {c}=await scored(t,'SURVIVED',{mode:'advise'});assert.equal((await m.handleHook(c,{},'Stop')).code,0);});
test('pending results block once then allow with warning',async t=>{const f=fixture(t,{gateBudgetSec:0});await m.register(f.c,f.test);assert.equal((await m.handleHook(f.c,{},'Stop')).code,2);assert.equal((await m.handleHook(f.c,{},'Stop')).code,0);});
test('waivers rescore fresh results and line changes invalidate IDs',async t=>{const f=await scored(t),r=m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]);f.put('.mutagate/waivers.json',JSON.stringify({schema:1,waivers:[{id:r.survivors[0].id,target:'acme.Foo',reason:'equivalent'}]}));assert.equal(m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]).score,1);await m.runTarget(f.c,f.key,async()=>({raw:raw('SURVIVED',2)}));assert.match(m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]).warnings[0],/no longer matches/);});
test('waiver protection covers all harnesses and patch renames',async t=>{const {c}=fixture(t);for(const harness of ['claude','codex','pi','opencode']){const r=await m.handleHook({...c,harness},{tool_name:'apply_patch',tool_input:{command:'*** Move to: .mutagate/waivers.json'}},'PreToolUse');assert.equal(r.out.hookSpecificOutput.permissionDecision,harness==='claude'?'ask':'deny');}});
test('source changes invalidate and old worker cannot publish a pass',async t=>{const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo');let runs=0;await m.runTarget(f.c,key,async()=>{runs++;if(runs===1){f.put(f.source,'package acme; class Foo { }');await m.register(f.c,f.test);}return {raw:raw(runs===1?'KILLED':'SURVIVED')};});assert.equal(runs,2);assert.equal(m.loadResult(f.c,key,m.state(f.c).targets[key]).status,'below');});
test('concurrent state writers preserve every update',async t=>{const {c}=fixture(t);await Promise.all(Array.from({length:20},(_,n)=>m.updateState(c,s=>{s.choices[n]=n;})));assert.equal(Object.keys(m.state(c).choices).length,20);});
test('lock released by its holder mid-contention does not crash other processes',async t=>{const {c}=fixture(t),code=`const m=await import(${JSON.stringify(new URL('../scripts/mutagate.mjs',import.meta.url).href)});for(let n=0;n<100;n++)await m.updateState({stateFile:${JSON.stringify(c.stateFile)}},s=>{s.choices[process.pid+'-'+n]=n;});`;const results=await Promise.all(Array.from({length:8},()=>new Promise(r=>{const p=spawn(process.execPath,['--input-type=module','-e',code],{stdio:['ignore','ignore','pipe']});let err='';p.stderr.on('data',d=>err+=d);p.on('close',status=>r({status,err}));})));assert.deepEqual(results.filter(r=>r.status!==0),[]);assert.equal(Object.keys(m.state(c).choices).length,800);});
test('install is idempotent and uninstall preserves unrelated hooks',t=>{const f=fixture(t);f.put('.claude/settings.json',JSON.stringify({permissions:{allow:['Read']},hooks:{Stop:[{hooks:[{type:'command',command:'echo retained'}]}]}}));m.install(f.c,'claude');const once=fs.readFileSync(path.join(f.c.repo,'.claude/settings.json'),'utf8');m.install(f.c,'claude');assert.equal(fs.readFileSync(path.join(f.c.repo,'.claude/settings.json'),'utf8'),once);m.install(f.c,'claude','project',true);const out=JSON.parse(fs.readFileSync(path.join(f.c.repo,'.claude/settings.json')));assert.equal(out.hooks.Stop[0].hooks[0].command,'echo retained');assert.deepEqual(out.permissions,{allow:['Read']});});
test('malformed and unknown hooks fail open at executable boundary',t=>{const {c}=fixture(t);for(const input of ['{',JSON.stringify({cwd:c.repo})]){const result=spawnSync(process.execPath,['scripts/mutagate.mjs','hook','Unknown'],{cwd:path.resolve(import.meta.dirname,'..'),input,encoding:'utf8'});assert.equal(result.status,0);assert.equal(result.stdout,'');}});
test('simultaneous completion events cannot exceed the round cap',async t=>{const {c}=await scored(t,'SURVIVED',{maxRounds:1});const results=await Promise.all([m.handleHook(c,{},'Stop'),m.handleHook(c,{},'Stop')]);assert.equal(results.filter(r=>r.code===2).length,1);assert.equal(Object.values(m.state(c).targets)[0].blocks,1);});
test('distinct mutations on one source line have distinct waiver IDs',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0];const r=m.normalize([{...raw()[0],mutation_key:'1'},{...raw()[0],mutation_key:'2'}],f.c,target);assert.notEqual(r.survivors[0].id,r.survivors[1].id);});
test('partial results cannot manufacture a passing score',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0];assert.equal(m.normalize([...raw('KILLED'),...raw('PENDING',2)],f.c,target).status,'unscored');});
test('waiver protection resolves an internal symlink alias',async t=>{const f=fixture(t);f.put('.mutagate/waivers.json','{"schema":1,"waivers":[]}');fs.symlinkSync(path.join(f.c.repo,'.mutagate/waivers.json'),path.join(f.c.repo,'alias.json'));const r=await m.handleHook(f.c,{tool_input:{file_path:'alias.json'}},'PreToolUse');assert.equal(r.out.hookSpecificOutput.permissionDecision,'ask');});
test('disabled languages do not register gate targets',async t=>{const f=fixture(t,{languages:['python']});assert.equal((await m.register(f.c,f.test)).disabled,true);assert.deepEqual(m.state(f.c).targets,{});});
test('same class name in separate modules keeps separate state',async t=>{const f=fixture(t);for(const module of ['a','b']){f.put(module+'/build.gradle',"plugins { id 'java' }");f.put(module+'/src/main/java/Foo.java','package acme; public class Foo {}');f.put(module+'/src/test/java/FooTest.java','package acme; public class FooTest {}');await m.register(f.c,module+'/src/test/java/FooTest.java');}assert.equal(Object.keys(m.state(f.c).targets).length,2);});
test('telemetry and optional jar rules do not require commercial artifacts for Tier B',()=>{const manifest=JSON.parse(fs.readFileSync(path.resolve(import.meta.dirname,'../references/jars.json')));assert.ok(manifest.some(x=>x.artifact==='pitest-kotlin-plugin'&&x.optional==='arcmutate'));assert.ok(manifest.every(x=>/^[a-f0-9]{64}$/.test(x.sha256)));});
test('resource edits invalidate a previously passing score',async t=>{const f=await scored(t,'KILLED');f.put('settings.yaml','feature: true\n');assert.equal(m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]),null);});
test('subagent writes and completion share the same isolated scope',t=>{const {c}=fixture(t);const post=m.context({repo:c.repo},{session_id:'parent',agent_id:'child',hook_event_name:'PostToolUse'}),stop=m.context({repo:c.repo},{session_id:'parent',agent_id:'child',hook_event_name:'SubagentStop'}),parent=m.context({repo:c.repo},{session_id:'parent'});assert.equal(post.session,stop.session);assert.notEqual(post.session,parent.session);for(const c of [post,stop,parent])assert.equal(c.agentSession,true);});
test('invalid configuration is announced once per session',async t=>{const {c}=fixture(t);c.errors=['invalid config'];assert.match((await m.handleHook(c,{},'SessionStart')).text,/invalid config/);assert.doesNotMatch((await m.handleHook(c,{},'SessionStart')).text,/invalid config/);});
test('Go and C# config, globs, language and result enums agree',t=>{const {c}=fixture(t);for(const [file,lang] of [['a/b_test.go','go'],['X.Tests/FooTests.cs','csharp']]){assert.ok(m.isTest(file));assert.equal(m.language(file),lang);}assert.equal(m.configFor(c.repo,c.root,{'go-runner':'gremlins','go-tags':'integration'},{MUTAGATE_GO_RUNNER:'gomutants'}).config.goRunner,'gremlins');assert.ok(m.configFor(c.repo,c.root,{'go-runner':'bad'},{}).errors.length);const schema=JSON.parse(fs.readFileSync(new URL('../references/result-schema.json',import.meta.url)));for(const lang of m.DEFAULTS.languages){assert.ok(schema.properties.language.enum.includes(lang));assert.ok(schema.properties.runner.enum.includes(m.RUNNER[lang]));}assert.ok(schema.properties.runner.enum.includes('gremlins'));});
test('Go targets prefer package sibling and exclude generated files at every depth',t=>{const {c,put}=fixture(t);put('mod/go.mod','module acme\ngo 1.26');put('mod/foo_test.go','package foo');put('mod/foo.go','package foo');put('mod/foo.pb.go','package foo');let r=m.resolveTargets(c,'mod/foo_test.go');assert.equal(r.targets[0].file,'mod/foo.go');assert.equal(r.targets[0].module,'mod');fs.unlinkSync(path.join(c.repo,'mod/foo.go'));assert.deepEqual(m.resolveTargets(c,'mod/foo_test.go').candidates,[]);for(const file of ['zz_generated.go','mock_foo.go','foo_gen.go','foo_mock.go','Migrations/Foo.cs','Foo.Designer.cs','Foo.g.cs','Foo.g.i.cs']){put(file,'');assert.throws(()=>m.resolveTargets(c,'mod/foo_test.go',file),/no production file matches/);}});
test('Go tests resolve to the only source file in their package, else list package files',t=>{const {c,put}=fixture(t);put('mod/go.mod','module acme\ngo 1.26');put('mod/matrix_controller.go','package rest');put('mod/api_integration_test.go','package rest_test');put('mod/index.html','');assert.equal(m.resolveTargets(c,'mod/api_integration_test.go').targets[0].file,'mod/matrix_controller.go');put('mod/errors.go','package rest');const r=m.resolveTargets(c,'mod/api_integration_test.go');assert.equal(r.ambiguous,true);assert.deepEqual(r.candidates.sort(),['mod/errors.go','mod/matrix_controller.go']);});
test('C# target lives in another project and excludes generated build sources',t=>{const {c,put}=fixture(t);put('Acme.Tests/Acme.Tests.csproj','<Project/>');put('Acme.Tests/PricingTests.cs','namespace Acme.Tests; class PricingTests {}');put('Acme/Acme.csproj','<Project/>');put('Acme/Pricing.cs','namespace Acme; class Pricing {}');put('Acme/Pricing.Designer.cs','class Pricing {}');put('Acme/obj/Pricing.cs','class Pricing {}');put('Acme/bin/Pricing.cs','class Pricing {}');const r=m.resolveTargets(c,'Acme.Tests/PricingTests.cs');assert.equal(r.targets[0].file,'Acme/Pricing.cs');assert.equal(r.targets[0].module,'Acme.Tests');assert.equal(r.targets.length,1);assert.throws(()=>m.resolveTargets(c,'Acme.Tests/PricingTests.cs','Acme/Pricing.Designer.cs'),/no production file matches/);});
test('mutation-testing-elements paths, identities and statuses normalize across tools',t=>{const {c,put}=fixture(t);put('mod/foo.go','package foo');const mutant={location:{start:{line:2,column:1},end:{line:2,column:3}},replacement:'0',mutatorName:'RETURN_ZERO'};for(const [key,root] of [[path.join(c.repo,'mod/foo.go'),'/irrelevant'],['foo.go',path.join(c.repo,'mod')],['mod/foo.go',undefined]]){const r=m.parseMutationTestingElements({projectRoot:root,files:{[key]:{mutants:['Killed','Survived','Timeout','NoCoverage','CompileError','RuntimeError','Ignored','Pending','Future'].map(status=>({...mutant,status}))}}},c.repo);assert.ok(r.every(x=>x.file==='mod/foo.go'));assert.deepEqual(r.map(x=>x.status),['KILLED','SURVIVED','TIMED_OUT','NO_COVERAGE','NON_VIABLE','RUN_ERROR','NON_VIABLE','PENDING','PENDING']);assert.equal(r[0].mutation_key,JSON.stringify([mutant.location,'0']));}assert.throws(()=>m.parseMutationTestingElements({},c.repo),/invalid/);});
test('mutation-testing-elements survivors show the replaced source text',t=>{const {c,put,test:tf}=fixture(t);put('mod/max.go','package foo\nconst Max = 1000\nvar é = 1000\n');const plain=(line,start,end,replacement='999')=>m.plainMutation(m.parseMutationTestingElements({files:{'mod/max.go':{mutants:[{location:{start:{line,column:start},end:{line:end[0],column:end[1]}},replacement,mutatorName:'INTEGER_DECREMENT',status:'Survived'}]}}},c.repo)[0],c);assert.equal(plain(2,13,[2,17]),'1000 became 999 and no test noticed');for(const x of [plain(2,13,[3,5]),plain(3,9,[3,13]),plain(2,13,[2,17],'9\n9'),plain(2,13,[2,17],' 999'),m.plainMutation({file:'mod/max.go',line:2,mutator:'INTEGER_DECREMENT',mutation_key:'not json'},c)])assert.equal(x,'increment changed and no test noticed');assert.equal(m.plainMutation({file:'mod/max.go',line:2,mutator:'BRANCH_IF',mutation_key:'not json'},c),'call or block removed and no test noticed');assert.equal(m.plainMutation({file:'mod/max.go',line:2,mutator:'ERRORF_WRAP',mutation_key:'not json'},c),'error wrapping (%w) dropped and no test noticed');const short=mutator=>m.normalize([{...raw()[0],mutator}],c,m.resolveTargets(c,tf).targets[0]).survivors[0].short;assert.deepEqual(['BRANCH_IF','EXPRESSION_REMOVE','ERRORF_WRAP'].map(short),['void-call','conditional','error-wrap']);});
test('gremlins parses spaced statuses and package-relative paths',()=>{const r=m.parseGremlins({files:[{file_name:'foo.go',mutations:['NOT COVERED','LIVED','TIMED OUT','KILLED','NOT VIABLE','SKIPPED','RUNNABLE','Future'].map(status=>({line:3,column:7,type:'CONDITIONALS_BOUNDARY',status}))}]},'mod/pkg');assert.ok(r.every(x=>x.file==='mod/pkg/foo.go'));assert.deepEqual(r.map(x=>x.status),['NO_COVERAGE','SURVIVED','TIMED_OUT','KILLED','NON_VIABLE','NON_VIABLE','PENDING','PENDING']);assert.throws(()=>m.parseGremlins({},''),/invalid/);});
test('C# fingerprints follow transitive references and ignore tool and build output',t=>{const {c,put}=fixture(t);c.root=path.join(c.repo,'cache-root');put('Acme.Tests/Acme.Tests.csproj','<Project><ProjectReference Include="../Acme/Acme.csproj"/></Project>');put('Acme.Tests/PricingTests.cs','class PricingTests {}');put('Acme/Acme.csproj',"<Project><ProjectReference Include='../Shared/Shared.csproj'/></Project>");put('Acme/Pricing.cs','class Pricing {}');put('Shared/Shared.csproj','<Project><ProjectReference Include="../Acme/Acme.csproj"/></Project>');put('Shared/Value.cs','class Value {}');put('Directory.Build.props','<Project/>');put('Acme.sln','solution');const target=m.resolveTargets(c,'Acme.Tests/PricingTests.cs').targets[0],files=inputFiles(c,target),before=m.fingerprint(c,target);for(const file of ['Shared/Value.cs','Acme/Pricing.cs','Acme.Tests/Acme.Tests.csproj','Directory.Build.props','Acme.sln'])assert.ok(files.includes(file),file);for(const file of ['Acme/obj/project.assets.json','Acme/bin/a.dll','cache-root/tools/dotnet-stryker','Acme/StrykerOutput/report.json','Acme/TestResults/report.xml'])put(file,'output');assert.equal(m.fingerprint(c,target),before);put('Shared/Value.cs','class Value { int n; }');assert.notEqual(m.fingerprint(c,target),before);});
test('Go fingerprints include module and workspace configuration',t=>{const {c,put}=fixture(t);put('mod/go.mod','module acme');put('mod/foo.go','package foo');put('mod/foo_test.go','package foo');put('go.work','go 1.26\nuse ./mod');put('go.work.sum','sum');const target=m.resolveTargets(c,'mod/foo_test.go').targets[0],files=inputFiles(c,target);for(const file of ['mod/go.mod','mod/foo.go','mod/foo_test.go','go.work','go.work.sum'])assert.ok(files.includes(file),file);});
test('tool installation honors cache, offline and deadline without starting expired work',async t=>{const {c,put}=fixture(t);const old=process.env.MUTAGATE_OFFLINE;t.after(()=>{if(old===undefined)delete process.env.MUTAGATE_OFFLINE;else process.env.MUTAGATE_OFFLINE=old;});process.env.MUTAGATE_OFFLINE='1';put('.cache/tools/gomutants@0.6.1/gomutants','cached');assert.equal(await m.tool(c,'gomutants',null),path.join(c.root,'tools/gomutants@0.6.1/gomutants'));await assert.rejects(m.tool(c,'gomutants',null,{deadline:Date.now()-1}),/budget exceeded/);await assert.rejects(m.tool(c,'mutagate-missing-tool',{exe:process.execPath,args:['-e','throw Error("must not run")']},{deadline:Date.now()+1000}),/unavailable/);});
test('Go auto falls back only to existing gremlins and preserves runner on errors',async t=>{const {c,put}=fixture(t);const oldPath=process.env.PATH;t.after(()=>{process.env.PATH=oldPath;});process.env.PATH=path.join(c.repo,'empty-path');put('mod/go.mod','module acme\ngo 1.26');put('mod/foo.go','package foo');put('mod/foo_test.go','package foo');put('.cache/tools/gremlins@0.6.0/gremlins',`#!${process.execPath}\nconst fs=require('node:fs');const out=process.argv.find(x=>x.startsWith('--output=')).slice(9);fs.writeFileSync(out,JSON.stringify({files:[{file_name:'foo.go',mutations:[{line:1,column:1,type:'CONDITIONALS_BOUNDARY',status:'LIVED'}]}]}));`);fs.chmodSync(path.join(c.root,'tools/gremlins@0.6.0/gremlins'),0o755);await m.register(c,'mod/foo_test.go');let r=await m.runTarget(c,m.targetKey(m.resolveTargets(c,'mod/foo_test.go').targets[0]));assert.equal(r.runner,'gremlins');assert.equal(r.status,'below');put('.cache/tools/gremlins@0.6.0/gremlins',`#!${process.execPath}\nprocess.exit(1);`);put('mod/foo.go','package foo\n// changed');r=await m.runTarget(c,m.targetKey(m.resolveTargets(c,'mod/foo_test.go').targets[0]));assert.equal(r.runner,'gremlins');assert.equal(r.status,'error');});
test('forced gomutants never falls back to cached gremlins',async t=>{const {c,put}=fixture(t,{goRunner:'gomutants'});const oldPath=process.env.PATH;t.after(()=>{process.env.PATH=oldPath;});process.env.PATH=path.join(c.repo,'empty-path');put('mod/go.mod','module acme');put('mod/foo.go','package foo');put('mod/foo_test.go','package foo');put('.cache/tools/gremlins@0.6.0/gremlins',`#!${process.execPath}\nthrow Error('must not run');`);fs.chmodSync(path.join(c.root,'tools/gremlins@0.6.0/gremlins'),0o755);const resolved=await m.register(c,'mod/foo_test.go');const r=await m.runTarget(c,m.targetKey(resolved.targets[0]));assert.equal(r.status,'error');assert.equal(r.runner,'gomutants');});
