test('gremlins refuses package-directory mismatch before reporting false kills',async t=>{const {c,put}=fixture(t,{goRunner:'gremlins'});put('mod/go.mod','module acme');put('mod/sub/foo.go','package different');put('mod/sub/foo_test.go','package different');put('.cache/tools/gremlins@0.6.0/gremlins','must not run');const r=await m.register(c,'mod/sub/foo_test.go'),result=await m.runTarget(c,m.targetKey(r.targets[0]));assert.equal(result.status,'error');assert.equal(result.runner,'gremlins');assert.match(result.error,/subdirectory name/);});
