test('auto mode never installs gremlins after gomutants installation fails',async t=>{const {c,put}=fixture(t);const oldPath=process.env.PATH;t.after(()=>{process.env.PATH=oldPath;});process.env.PATH=path.join(c.repo,'fake-bin');put('fake-bin/go',`#!${process.execPath}\nrequire('node:fs').appendFileSync(${JSON.stringify(path.join(c.repo,'install-calls'))},process.argv.slice(2).join(' ')+'\\n');process.exit(1);`);fs.chmodSync(path.join(c.repo,'fake-bin/go'),0o755);put('mod/go.mod','module acme');put('mod/foo.go','package foo');put('mod/foo_test.go','package foo');const r=await m.register(c,'mod/foo_test.go'),result=await m.runTarget(c,m.targetKey(r.targets[0]));assert.equal(result.status,'error');assert.equal(fs.readFileSync(path.join(c.repo,'install-calls'),'utf8').trim(),'install '+m.TOOLS.gomutants);assert.match(result.error,/gomutants@v0.6.1/);assert.match(result.error,/gremlins@v0.6.0/);});
test('expired Go installation is unscored and cannot fall back',async t=>{const {c,put}=fixture(t);const oldPath=process.env.PATH;t.after(()=>{process.env.PATH=oldPath;});process.env.PATH=path.join(c.repo,'fake-bin');c.config.runBudgetSec=.15;put('fake-bin/go',`#!${process.execPath}\nsetTimeout(()=>{},10000);`);fs.chmodSync(path.join(c.repo,'fake-bin/go'),0o755);put('.cache/tools/gremlins@0.6.0/gremlins',`#!${process.execPath}\nthrow Error('must not run');`);fs.chmodSync(path.join(c.root,'tools/gremlins@0.6.0/gremlins'),0o755);put('mod/go.mod','module acme');put('mod/foo.go','package foo');put('mod/foo_test.go','package foo');const r=await m.register(c,'mod/foo_test.go'),result=await m.runTarget(c,m.targetKey(r.targets[0]));assert.equal(result.status,'unscored');assert.equal(result.runner,'gomutants');});
test('CLI runs when invoked through a symlinked path',t=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'mutagate-link-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const link=path.join(dir,'scripts');fs.symlinkSync(path.resolve(import.meta.dirname,'../scripts'),link,'dir');for(const f of ['mutagate.mjs','mutagate-hook.cjs'])assert.match(spawnSync(process.execPath,[path.join(link,f),'status','--json','--repo',dir],{encoding:'utf8'}).stdout,/\S/,f);});
test('JUnit launcher resolves beside the engine jar or fails naming coordinates',async t=>{const {c,put}=fixture(t);const jar=a=>`m2/org/junit/platform/junit-platform-${a}/6.0.3/junit-platform-${a}-6.0.3.jar`,engine=path.join(c.repo,jar('engine')),calls=path.join(c.repo,'calls'),jup='/x/junit-jupiter-api-6.0.3.jar';put(jar('engine'),'');put(jar('launcher'),'');assert.equal(await m.launcherJar([engine,jup],null,{}),path.join(c.repo,jar('launcher')));assert.equal(await m.launcherJar([engine,jup,'/x/junit-platform-launcher-6.0.3.jar'],null,{}),null);assert.equal(await m.launcherJar([engine],null,{}),null);assert.equal(await m.launcherJar(['/x/junit-4.13.2.jar'],null,{}),null);fs.unlinkSync(path.join(c.repo,jar('launcher')));put('mvnw',`#!${process.execPath}\nrequire('node:fs').writeFileSync(${JSON.stringify(calls)},process.argv.slice(2).join(' '));`);fs.chmodSync(path.join(c.repo,'mvnw'),0o755);await assert.rejects(m.launcherJar([engine,jup],path.join(c.repo,'mvnw'),{}),/junit-platform-launcher:6\.0\.3/);assert.match(fs.readFileSync(calls,'utf8'),/dependency:get .*junit-platform-launcher:6\.0\.3 -Dtransitive=false/);await assert.rejects(m.launcherJar([engine,jup],null,{}),/junit-platform-launcher:6\.0\.3/);});
test('failed commands name the cause and runs keep a truncated per-target log',async t=>{await assert.rejects(m.command(process.execPath,['-e','console.error("VM : x\\njava.lang.NoClassDefFoundError: org/junit/x\\n\\tat a.b(C.java:1)\\nInput ->");process.exit(1)']),e=>/NoClassDefFoundError/.test(e.message)&&!/\tat |Input ->/.test(e.message));await assert.rejects(m.command(process.execPath,['-e','console.log("[ERROR] /a/Foo.java:[3,1] cannot find symbol\\n/a/Foo.java:3: error: cannot find symbol\\nFAILURE: Build failed with an exception.\\nExecution failed for task :compileJava.\\n> Compilation failed; see the compiler error output for details.\\nBUILD FAILED in 1s\\n[ERROR] \\n[ERROR] -> [Help 1]\\n[ERROR] Re-run Maven using the -X switch\\n[ERROR] For more information about the errors\\n[ERROR] [Help 1] http://x/CompilationFailureException");process.exit(1)']),e=>/cannot find symbol \| .*cannot find symbol$/.test(e.message)&&!/Help|FAILURE|BUILD|Execution|Compilation failed/.test(e.message));await assert.rejects(m.command(process.execPath,['-e','console.error("FAILURE: Build failed with an exception.\\n\\n* What went wrong:\\nExecution failed for task :compileTestJava.\\n> Could not find org.junit.jupiter:junit-jupiter:9.9.9.\\n\\n* Try:\\n> Run with --stacktrace option to get the stack trace.\\n\\nBUILD FAILED in 2s");process.exit(1)']),/failed \(1\): > Could not find org\.junit\.jupiter:junit-jupiter:9\.9\.9\.$/);const f=fixture(t);await m.register(f.c,f.test);for(let n=0;n<2;n++){const r=await m.runTarget(f.c,m.hash('acme.Foo'),async(c,t,dir,opts)=>{fs.appendFileSync(opts.log,'line\n');throw Error('boom');});assert.match(r.error,/^boom; log: /);assert.equal(fs.readFileSync(r.error.split('; log: ')[1],'utf8'),'line\n');}});
test('integration test names resolve by prefix and unresolved JVM tests list package candidates',t=>{const {c,put}=fixture(t);put('src/main/java/acme/BarController.java','package acme; public class BarController {}');put('src/test/java/acme/BarIntegrationTests.java','package acme; class BarIntegrationTests {}');put('src/test/java/acme/ZzzIntegrationTests.java','package acme; class ZzzIntegrationTests {}');put('src/main/java/Top.java','public class Top {}');put('src/test/java/QqqIntegrationTests.java','class QqqIntegrationTests {}');assert.equal(m.resolveTargets(c,'src/test/java/acme/BarIntegrationTests.java').targets[0].target,'acme.BarController');const r=m.resolveTargets(c,'src/test/java/acme/ZzzIntegrationTests.java');assert.equal(r.ambiguous,true);assert.ok(['acme.Foo','acme.BarController'].every(x=>r.candidates.includes(x)),r.message);assert.deepEqual(m.resolveTargets(c,'src/test/java/QqqIntegrationTests.java').candidates,['Top']);});
const SESSION_ENV=['MUTAGATE_SESSION','CLAUDE_CODE_SESSION_ID','CODEX_THREAD_ID','MUTAGATE_HOOK_SESSION'];
function sessionEnv(t,env={}){const old={...process.env},set=e=>{for(const k of SESSION_ENV)if(e[k]===undefined)delete process.env[k];else process.env[k]=e[k];};t.after(()=>set(old));set(env);return set;}
