test('unresolved targets are announced once and stay in completion warnings',async t=>{const f=fixture(t);f.put('src/main/java/acme/Foo2.java','package acme; public class Foo2 {}');f.put('src/test/java/acme/QuxTest.java','package acme; public class QuxTest {}');const post=(id,file)=>m.handleHook(f.c,{tool_use_id:id,tool_input:{file_path:file}},'PostToolUse');assert.match((await post('a','src/test/java/acme/QuxTest.java')).out.hookSpecificOutput.additionalContext,/target unresolved for src\/test\/java\/acme\/QuxTest\.java/);assert.equal((await m.handleHook({...f.c,args:{mutate:true}},{tool_use_id:'b',tool_input:{file_path:'src/test/java/acme/QuxTest.java'}},'PostToolUse')).out,undefined);assert.equal((await post('c','src/test/java/acme/QuxTest.java')).out,undefined);await post('d',f.test);assert.equal(m.state(f.c).warnings.length,1);await m.register(f.c,'src/test/java/acme/QuxTest.java','acme.Foo2');assert.deepEqual(m.state(f.c).warnings,[]);});
test('async mutation handler yields to newer edits and skips fresh targets',async t=>{const f=await scored(t,'KILLED');const post=(id,mutate)=>m.handleHook({...f.c,args:mutate?{mutate:true}:{}},{tool_use_id:id,tool_input:{file_path:f.test}},'PostToolUse');await post('a');await post('b');const started=Date.now();assert.equal((await post('a',true)).code,0);assert.ok(Date.now()-started<1000);await m.runTarget(f.c,f.key,async()=>({raw:raw('KILLED')}));const before=fs.readFileSync(path.join(f.c.data,'results/test',f.key+'.json'),'utf8');await m.updateState(f.c,s=>{s.editedAt=0;});assert.equal((await post('b',true)).code,0);assert.equal(fs.readFileSync(path.join(f.c.data,'results/test',f.key+'.json'),'utf8'),before);});
test('async mutation handler waits for a build running in the repo',{skip:process.platform==='win32'},async t=>{const f=await scored(t,'KILLED');const build=spawn(process.execPath,['-e','setTimeout(()=>{},30000)','org.codehaus.plexus.classworlds.launcher.Launcher',`-Dmaven.multiModuleProjectDirectory=${f.c.repo}`]);t.after(()=>build.kill());await new Promise(r=>setTimeout(r,300));assert.equal(m.buildRunning(f.c),true);assert.equal(m.buildRunning({repo:f.c.repo.slice(0,-1)}),false);await m.handleHook(f.c,{tool_use_id:'a',tool_input:{file_path:f.test}},'PostToolUse');await m.updateState(f.c,s=>{s.editedAt=0;});f.put(f.source,'package acme; public class Foo { public int price(int n) { return n > 5 ? 10 : 20; }}');const started=Date.now(),hook=m.handleHook({...f.c,args:{mutate:true}},{tool_use_id:'a',tool_input:{file_path:f.test}},'PostToolUse');await new Promise(r=>setTimeout(r,1500));await m.runTarget(f.c,f.key,async()=>({raw:raw('KILLED')}));build.kill();assert.deepEqual(await hook,{code:0});assert.ok(Date.now()-started>=1500);});
