test('hook trace marks the async --mutate PostToolUse run',t=>{const {c}=fixture(t),cache=path.join(c.repo,'.cache');for(const exe of ['mutagate.mjs','mutagate-hook.cjs'])for(const extra of [[],['--mutate']])spawnSync(process.execPath,[path.resolve(import.meta.dirname,'../scripts',exe),'hook','PostToolUse',...extra],{input:JSON.stringify({cwd:c.repo,session_id:'s',tool_name:'Write',tool_input:{file_path:'src/main/java/acme/Foo.java'}}),env:{...process.env,CLAUDE_PLUGIN_DATA:cache,MUTAGATE_HARNESS:'claude',MUTAGATE_TRACE:'1'},encoding:'utf8'});const trace=fs.readFileSync(path.join(cache,'repos',m.hash(c.repo),'trace.jsonl'),'utf8').trim().split('\n').map(JSON.parse);assert.deepEqual(trace.map(r=>[r.event,r.mutate]),[['PostToolUse',false],['PostToolUse',true],['PostToolUse',false],['PostToolUse',true]]);});
test('mutmut config and result bridge follow the installed mutmut version',()=>{const t={file:'pricing.py',tests:['tests/test_pricing.py']},toml=(a,b)=>tomlConfig(a,b,t);assert.equal(toml(2,5),'');assert.match(toml(3,3),/^\n\[tool\.mutmut\]\npaths_to_mutate = \["pricing\.py"\]\ntests_dir = \["tests\/test_pricing\.py"\]\npytest_add_cli_args = \["-x","-q","tests\/test_pricing\.py"\]\n$/);for(const v of [[3,6],[3,8],[3,12]]){const s=toml(...v);assert.match(s,/^\n\[tool\.mutmut\]\nsource_paths = \["pricing\.py"\]\n/);assert.match(s,/\npytest_add_cli_args_test_selection = \["tests\/test_pricing\.py"\]\n/);assert.match(s,/\nuse_setproctitle = false\n/);assert.doesNotMatch(s,/tests_dir|paths_to_mutate/);}
  const b=(a,v)=>bridgeSource(a,v);assert.match(b(2,5),/cache\.Mutant\.select\(\)/);assert.doesNotMatch(b(2,5),/mutmut\.__main__/);assert.match(b(3,5),/mm\.ensure_config_loaded\(\)/);assert.match(b(3,5),/should_ignore_for_mutation/);assert.doesNotMatch(b(3,5),/should_mutate|configuration/);
  for(const v of [6,7,8]){const s=b(3,v);assert.match(s,/Config\.ensure_loaded\(\)/);assert.match(s,/mc\.config\(\)/);assert.match(s,/should_mutate\(file\)/);assert.match(s,/format_utils/);assert.doesNotMatch(s,/ensure_config_loaded|should_ignore_for_mutation|cache\.Mutant/);}for(const s of [b(2,5),b(3,5),b(3,8)])assert.match(s,/print\(json\.dumps\(out\)\)\s*$/);});
test('an error result is re-run once by check, then returned as final; an edit resets the attempts',async t=>{const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo');let runs=0;const jdk=async()=>{runs++;throw Error('missing JDK');};const attempts=()=>m.loadResult(f.c,key,m.state(f.c).targets[key]).attempts;await m.runTarget(f.c,key,jdk);assert.equal(attempts(),1);assert.equal((await m.gate(f.c,{runner:jdk})).code,3);assert.equal(runs,2);assert.equal(attempts(),2);assert.equal((await m.gate(f.c,{runner:jdk})).code,3);assert.equal(runs,2);f.put('src/main/java/acme/Bar.java','package acme; class Bar {}');await m.runTarget(f.c,key,jdk);assert.equal(attempts(),1);assert.equal((await m.gate(f.c,{runner:async()=>({raw:raw('KILLED')})})).code,0);});
test('agent-caused errors: a failing runner line naming a registered test or a baseline-red message; warnings and infrastructure are not',async t=>{const {agentCause}=await import('../scripts/errors.cjs'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'mutagate-log-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const log=(...entries)=>{const p=path.join(dir,String(Math.random()));fs.writeFileSync(p,entries.map(e=>JSON.stringify({exe:'x',args:['Matrix.Tests/MatrixServiceTests.cs'],error:'',...e})+'\n').join(''));return p;};const tests=['Matrix.Tests/MatrixServiceTests.cs'];
  const cs='/tmp/r/Matrix.Tests/MatrixServiceTests.cs(7,6): error CS0246: The type or namespace name \'Fact\' could not be found (are you missing a using directive or an assembly reference?) [/tmp/r/Matrix.Tests/Matrix.Tests.csproj]';
  assert.equal(agentCause('dotnet-stryker failed (1): 2 Error(s) | Initial build of targeted project failed. Please make sure the targeted project | is buildable. You can reproduce this error yourself using: "',tests,log({code:1,output:'  Matrix.Tests -> /tmp/r/Matrix.Tests/bin/Matrix.Tests.dll\n'+cs+'\n    2 Error(s)'})),cs);
  assert.equal(agentCause('dotnet-stryker failed (1): x',tests,log({code:0,output:cs},{code:1,output:'/tmp/r/Matrix.Tests/MatrixServiceTests.cs(3,1): warning CS8618: Non-nullable field'})),'');
  assert.equal(agentCause('mvn failed (1): [ERROR] /tmp/r/src/test/java/acme/FooTest.java:[36,35] cannot find symbol',['src/test/java/acme/FooTest.java']),'mvn failed (1): [ERROR] /tmp/r/src/test/java/acme/FooTest.java:[36,35] cannot find symbol');
  for(const [message,output] of [['pitest failed (1): java.lang.RuntimeException: 1 tests did not pass without mutation when calculating line coverage. Mutation testing requires a green suite.',''],['stryker failed (1): There were failed tests in the initial test run.',''],['dotnet-stryker failed (1): Initial testrun has failing tests.',''],['dotnet-stryker failed (1): Initial testrun has more than 50% failing tests.',''],['gomutants failed (1): FAIL | gomutants: coverage run failed: exit status 1','--- FAIL: TestAdd (0.00s)\nFAIL'],['gomutants failed (1): gomutants: coverage run failed: exit status 1','# example.com/m/internal/x [example.com/m/internal/x.test]\ninternal/x/api_unit_test.go:5:2: undefined: Foo'],['mutmut returned no parseable mutants; enable MUTAGATE_DEBUG=1 for runner logs','RuntimeError: Tests don\'t run cleanly without mutations. Test command was: python -m pytest -x -q'],['mutmut returned no parseable mutants; enable MUTAGATE_DEBUG=1 for runner logs','failed to collect stats. runner returned 1'],['mutmut returned no parseable mutants; enable MUTAGATE_DEBUG=1 for runner logs','Failed to run clean test']])assert.notEqual(agentCause(message,['tests/test_foo.py'],log({code:1,output})),'',message);
  const mm='mutmut failed (1): failed to collect stats. runner returned 1',red='FAILED tests/test_api.py::test_red - assert False';assert.equal(agentCause(mm,['tests/test_api.py'],log({code:1,output:'.F\n'+red+'\n1 failed'})),red);assert.equal(agentCause(mm,['tests/test_api.py'],log({code:1,output:'1 failed'})),mm);
  for(const message of ['missing JDK','JDK 11 or later is required','dotnet-stryker unavailable: spawn dotnet-stryker ENOENT','jar download failed: 503 pitest','no .csproj above Matrix.Tests/MatrixServiceTests.cs','multiple .csproj files above Matrix.Tests/MatrixServiceTests.cs; use one project per directory'])assert.equal(agentCause(message,tests,path.join(dir,'missing.log')),'',message);
  // A failing baseline `go test` is the tests' fault only when a test fails or a test file does not compile, not for production or module errors.
  for(const output of ['# example.com/m\n./api.go:3:1: syntax error: non-declaration statement outside function body\nFAIL\texample.com/m [build failed]','go: example.com/dep@v1.0.0: missing go.sum entry for go.mod file\nFAIL\texample.com/m [setup failed]'])assert.equal(agentCause('gomutants failed (1): gomutants: coverage run failed: exit status 1',['api_test.go'],log({code:1,output})),'',output);});
test('an agent-caused error blocks the first Stop with the cause and the fix, and the next Stop allows with a warning',async t=>{const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo');const red=async(c,tt,dir,opts)=>{fs.appendFileSync(opts.log,JSON.stringify({exe:'gradlew',args:[],code:1,output:path.join(f.c.repo,f.test)+':3: error: cannot find symbol',error:''})+'\n');throw Error('gradlew failed (1): > Compilation error. See log for more details | > Task :compileTestJava FAILED');};await m.runTarget(f.c,key,red);await m.runTarget(f.c,key,red);const first=await m.handleHook(f.c,{},'Stop');assert.equal(first.code,2);assert.equal(first.out.decision,'block');assert.match(first.out.reason,/FooTest\.java:3: error: cannot find symbol/);assert.match(first.out.reason,/Fix the failing or non-compiling tests/);const second=await m.handleHook(f.c,{},'Stop');assert.equal(second.code,0);assert.match(second.out.systemMessage,/cannot find symbol/);});
