test('Stop reports suppress unchanged async reports after edits including volatile error details',async t=>{for(const error of [false,true]){const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo'),runner=n=>async()=>{if(error)throw Error(`missing JDK 2026-09-15T12:00:0${n}.000Z log: /tmp/run-${n} pid ${n} ${n} ms`);return {raw:raw()};};await m.runTarget(f.c,key,runner(1));if(error)await m.runTarget(f.c,key,runner(1));const stop=await m.handleHook(f.c,{},'Stop');assert.equal(stop.code,error?0:2);f.put('src/main/java/acme/Bar.java','package acme; class Bar {}');await m.updateState(f.c,s=>{s.editedAt=0;});assert.deepEqual(await m.handleHook({...f.c,args:{mutate:true},runner:runner(2)},{tool_input:{file_path:f.test}},'PostToolUse'),{code:0});}});
test('Python probes uv projects without locks and explains missing mutmut',async t=>{const oldPath=process.env.PATH,oldVenv=process.env.VIRTUAL_ENV;t.after(()=>{process.env.PATH=oldPath;if(oldVenv===undefined)delete process.env.VIRTUAL_ENV;else process.env.VIRTUAL_ENV=oldVenv;});delete process.env.VIRTUAL_ENV;for(const marker of ['[dependency-groups]','[tool.uv]','build-backend = "uv_build"','lock','pip']){const {c,put}=fixture(t);put('pricing.py','def price(n): return n+1\n');put('tests/test_pricing.py','from pricing import price\n');if(marker==='lock')put('uv.lock','');else if(marker!=='pip')put('pyproject.toml',marker);put('fake-bin/'+(marker==='pip'?'python3':'uv'),`#!${process.execPath}\nconsole.error('missing package metadata');process.exit(1);`);fs.chmodSync(path.join(c.repo,'fake-bin',marker==='pip'?'python3':'uv'),0o755);process.env.PATH=path.join(c.repo,'fake-bin');const rr=await m.register(c,'tests/test_pricing.py'),r=await m.runTarget(c,m.targetKey(rr.targets[0]));assert.equal(r.status,'error');assert.match(r.error,/mutmut 2 or 3 must be installed/);assert.match(r.error,marker==='pip'?/pip install mutmut/:/uv add --dev mutmut, then uv sync/);assert.match(r.error,/failed \(1\)/);}});
test('CLI run rejects production files directories and unknown targets without error traces',t=>{const {c,test:tf,source}=fixture(t),cli=(...args)=>spawnSync(process.execPath,[path.resolve(import.meta.dirname,'../scripts/mutagate.mjs'),...args,'--repo',c.repo],{env:{...process.env,CLAUDE_PLUGIN_DATA:c.root,MUTAGATE_TRACE:'1'},encoding:'utf8'});for(const [args,message] of [[['run',source,'--target','x'],/not a test file/],[['run',tf,'--target','Nope'],/no production file matches/],[['run','src'],/test file/]]){const r=cli(...args);assert.equal(r.status,2,r.stderr);assert.match(r.stderr,message);}const trace=path.join(c.data,'trace.jsonl');assert.ok(!fs.existsSync(trace)||fs.readFileSync(trace,'utf8').trim().split('\n').map(JSON.parse).every(r=>r.decision!=='error'));const hook=spawnSync(process.execPath,[path.resolve(import.meta.dirname,'../scripts/mutagate.mjs'),'hook','PostToolUse'],{input:JSON.stringify({cwd:c.repo,session_id:'validation',tool_name:'Write',tool_input:{file_path:source}}),env:{...process.env,CLAUDE_PLUGIN_DATA:c.root},encoding:'utf8'});assert.equal(hook.status,0,hook.stderr);});
test('CLI waive distinguishes stale results and protects agent application while allowing human application',async t=>{const f=fixture(t),sid='waiver-session';f.c.sid=sid;f.c.session=m.hash(sid);f.c.stateFile=path.join(f.c.data,'state',f.c.session+'.json');await m.register(f.c,f.test);const r=await m.runTarget(f.c,m.hash('acme.Foo'),async()=>({raw:raw()})),id=r.survivors[0].id,env={...process.env,CLAUDE_PLUGIN_DATA:f.c.root,MUTAGATE_SESSION:sid};for(const name of ['MUTAGATE_HOOK_SESSION','CODEX_THREAD_ID','CLAUDE_CODE_SESSION_ID'])delete env[name];const cli=(extra={},apply=true)=>spawnSync(process.execPath,[path.resolve(import.meta.dirname,'../scripts/mutagate.mjs'),'waive',id,'--reason','equivalent',...(apply?['--apply']:[]),'--repo',f.c.repo],{env:{...env,...extra},encoding:'utf8'}),waivers=path.join(f.c.repo,'.mutagate/waivers.json');for(const name of ['MUTAGATE_HOOK_SESSION','CODEX_THREAD_ID','CLAUDE_CODE_SESSION_ID']){const blocked=cli({[name]:sid});assert.equal(blocked.status,2,blocked.stderr);assert.match(blocked.stderr,/--apply is for humans/);assert.equal(fs.existsSync(waivers),false);assert.equal(cli({[name]:sid},false).status,0);}assert.equal(cli().status,0);assert.equal(JSON.parse(fs.readFileSync(waivers)).waivers[0].id,id);fs.rmSync(waivers);f.put(f.source,'package acme; class Foo { int x; }');const stale=cli({},false);assert.equal(stale.status,2);assert.match(stale.stderr,/re-scored.*check --wait 120/);f.put('.mutagate/config.json','{"allowAgentWaivers":true}');f.c.config.allowAgentWaivers=true;await m.runTarget(f.c,m.hash('acme.Foo'),async()=>({raw:raw()}));const allowed=cli({MUTAGATE_HOOK_SESSION:sid});assert.equal(allowed.status,0,allowed.stderr);assert.equal(fs.existsSync(waivers),true);});
test('status JSON identifies production file and all registered tests',async t=>{const f=await scored(t);f.put('src/test/java/acme/FooMoreTest.java','package acme; class FooMoreTest {}');await m.register(f.c,'src/test/java/acme/FooMoreTest.java',f.source);const [entry]=JSON.parse(m.status(f.c,true));assert.equal(entry.file,f.source);assert.deepEqual(entry.tests,[f.test,'src/test/java/acme/FooMoreTest.java']);});
test('test support files are neither registered nor offered as production',async t=>{const {c,put}=fixture(t);put('tests/conftest.py','import pytest');put('tests/__init__.py','');put('matrix/svc.py','def f(): return 1');put('tests/test_zzz.py','import matrix');const post=f=>m.handleHook(c,{tool_use_id:f,tool_name:'Write',tool_input:{file_path:path.join(c.repo,f)}},'PostToolUse');await post('tests/conftest.py');await post('tests/__init__.py');assert.deepEqual(m.state(c).edited??[],[]);assert.deepEqual(Object.keys(m.state(c).targets),[]);assert.throws(()=>m.resolveTargets(c,'tests/conftest.py'),/not a test file/);const r=m.resolveTargets(c,'tests/test_zzz.py');assert.ok(r.ambiguous&&!r.candidates.includes('tests/conftest.py'),r.message);});
test('PIT zero-unit runs are unscored with no mutants; a missing report otherwise errors',()=>{assert.deepEqual(m.pitRaw('PIT >> INFO : Created 0 mutation test units\nRunning 0 units','/nonexistent/mutations.xml'),[]);assert.throws(()=>m.pitRaw('Created 1 mutation test units','/nonexistent/mutations.xml'),/ENOENT/);});
test('a failed mutmut run with no mutants is an error; a clean empty run is unscored',async t=>{const oldPath=process.env.PATH,oldVenv=process.env.VIRTUAL_ENV;t.after(()=>{process.env.PATH=oldPath;if(oldVenv===undefined)delete process.env.VIRTUAL_ENV;else process.env.VIRTUAL_ENV=oldVenv;});delete process.env.VIRTUAL_ENV;for(const code of [1,0]){const {c,put}=fixture(t);put('pricing.py','def price(n): return n+1\n');put('tests/test_pricing.py','from pricing import price\ndef test_price(): assert price(1)==2\n');put('fake-bin/python3',`#!${process.execPath}\nconst a=process.argv.slice(2);if(a[1]?.includes('importlib.metadata'))console.log('3.8.0');else if(a.includes('run')){console.error('Traceback (most recent call last):\\nModuleNotFoundError: No module named x');process.exit(${code});}else console.log('[]');`);fs.chmodSync(path.join(c.repo,'fake-bin/python3'),0o755);process.env.PATH=path.join(c.repo,'fake-bin');const rr=await m.register(c,'tests/test_pricing.py'),r=await m.runTarget(c,m.targetKey(rr.targets[0]));if(code){assert.equal(r.status,'error');assert.equal(r.agent_caused,false,r.error);assert.match(r.error,/mutmut failed \(1\)/);}else{assert.equal(r.status,'unscored');assert.match(r.error,/^no mutants to test/);}}});
test('review: explicit wait funds sequential targets and default hooks stay bounded',async t=>{const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo');await m.updateState(f.c,s=>{s.targets[key].lastRunMs=200000;});let calls=0;const runner=async()=>{calls++;return {raw:raw('KILLED')};};assert.equal((await m.gate(f.c,{hook:true,runner})).code,1);assert.equal(calls,0);assert.equal((await m.gate(f.c,{wait:300,runner})).code,0);assert.equal(calls,1);
  const g=fixture(t);for(const name of ['A','B','C','D']){g.put(`src/main/java/acme/${name}.java`,`package acme; class ${name} {}`);g.put(`src/test/java/acme/${name}Test.java`,`package acme; class ${name}Test {}`);await m.register(g.c,`src/test/java/acme/${name}Test.java`);}await m.updateState(g.c,s=>{for(const x of Object.values(s.targets))x.lastRunMs=40000;});let now=Date.now(),runs=0;t.mock.method(Date,'now',()=>now);const result=await m.gate(g.c,{wait:200,runner:async(c,target,dir,opts)=>{assert.ok(opts.deadline-now>=40000);now+=40000;runs++;return {raw:[]};}});assert.equal(runs,4);assert.equal(result.code,0);
});
test('review: retry advice survives cached errors and concurrent target deletion',async t=>{const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo');await m.runTarget(f.c,key,async()=>{throw Error('missing JDK');});await m.updateState(f.c,s=>{s.targets[key].lastRunMs=200000;});const g=await m.gate(f.c);assert.equal(g.code,3);assert.match(g.report,/needs about 200 s/);assert.match(g.report,/check --wait 30[12]/);await m.updateState(f.c,s=>{s.targets[key].lastRunMs=0;});const gone=await m.gate(f.c,{runner:async()=>{await m.updateState(f.c,s=>{delete s.targets[key];});return {raw:[]};}});assert.equal(gone.code,0);assert.doesNotMatch(gone.report,/acme.Foo/);});
test('review: unscored error counts include uncovered mutants',t=>{const f=fixture(t,{countNoCoverage:false}),target=m.resolveTargets(f.c,f.test).targets[0],result=m.normalize([...raw('RUN_ERROR'),...raw('NO_COVERAGE',2)],f.c,target);assert.equal(result.status,'unscored');assert.match(result.error,/1 of 2/);assert.doesNotMatch(result.error,/every mutant errored/);});
test('review: interrupted scratch manifest publication keeps deletion history',async t=>{const {scratch}=await import('../scripts/dotnet.cjs'),{c,put}=fixture(t);put('A/A.csproj','<Project/>');put('A/Old.cs','class Old {}');put('T/T.csproj','<Project/>');put('T/ATests.cs','class ATests {}');const target={tests:['T/ATests.cs']},inputs=()=>['A/A.csproj','A/Old.cs','T/T.csproj','T/ATests.cs'],dir=scratch(c,target,inputs),manifest=path.join(dir,'.copied.json'),original=fs.writeFileSync;const mock=t.mock.method(fs,'writeFileSync',function(file,data,...args){if(String(file).startsWith(manifest)){original.call(fs,file,'[',...args);throw Error('interrupted manifest write');}return original.call(fs,file,data,...args);});assert.throws(()=>scratch(c,target,inputs),/interrupted/);mock.mock.restore();assert.deepEqual(JSON.parse(fs.readFileSync(manifest,'utf8')),inputs());scratch(c,target,()=>inputs().filter(f=>f!=='A/Old.cs'));assert.equal(fs.existsSync(path.join(dir,'A/Old.cs')),false);});
test('budget policy: configured inflight wait never enlarges a hook or bare check',async t=>{for(const event of ['Stop','SubagentStop','TaskCompleted']){const f=fixture(t,{gateWaitSec:300});await m.register(f.c,f.test);await m.updateState(f.c,s=>{s.targets[m.hash('acme.Foo')].lastRunMs=200000;});const g=await m.handleHook(f.c,{},event);assert.equal(g.code,2,event);assert.match(g.err,/needs about 200 s/,event);}const f=fixture(t,{gateWaitSec:300});await m.register(f.c,f.test);await m.updateState(f.c,s=>{s.targets[m.hash('acme.Foo')].lastRunMs=200000;});let calls=0;const runner=async()=>{calls++;return {raw:[]};};assert.equal((await m.gate(f.c,{runner})).code,1);assert.equal(calls,0);assert.equal((await m.gate(f.c,{wait:300,runner})).code,0);assert.equal(calls,1);});
test('budget policy: over-budget history permits full attempts and gives one recovery instruction',async t=>{for(const fail of [false,true]){const f=fixture(t);await m.register(f.c,f.test);await m.updateState(f.c,s=>{s.targets[m.hash('acme.Foo')].lastRunMs=300001;});let calls=0;const runner=async()=>{calls++;if(fail)throw Error('mutation run budget exceeded');return {raw:[]};};const hook=await m.gate(f.c,{hook:true,wait:600,runner});assert.equal(calls,0);assert.match(hook.reason,/raise runBudgetSec/);assert.doesNotMatch(hook.reason,/--wait/);const result=await m.gate(f.c,{wait:600,runner});assert.equal(calls,1);assert.equal(result.code,fail?1:0);assert.doesNotMatch(result.report,/results pending/);await m.gate(f.c,{wait:600});assert.equal(calls,1);}});
test('Python package-member imports register alias and multiline secondary targets',async t=>{const {c,put}=fixture(t);for(const name of ['page','service','api'])put(`matrix/${name}.py`,'def value(): return 1\n');put('tests/test_page.py','from matrix import page, service as svc\nfrom matrix import (\n    api,\n)\n');const r=m.resolveTargets(c,'tests/test_page.py');assert.deepEqual(r.targets.map(x=>[x.target,x.secondary]),[['matrix/page.py',false],['matrix/api.py',true],['matrix/service.py',true]]);await m.register(c,'tests/test_page.py');assert.deepEqual(Object.values(m.state(c).targets).map(x=>x.target).sort(),['matrix/api.py','matrix/page.py','matrix/service.py']);});
test('Python uncovered target names the tests and blocks once as agent-caused',async t=>{const oldPath=process.env.PATH,oldVenv=process.env.VIRTUAL_ENV;t.after(()=>{process.env.PATH=oldPath;if(oldVenv===undefined)delete process.env.VIRTUAL_ENV;else process.env.VIRTUAL_ENV=oldVenv;});delete process.env.VIRTUAL_ENV;const {c,put}=fixture(t);put('pricing.py','def price(n): return n+1\n');put('tests/test_pricing.py','def test_price(): assert 1==1\n');put('fake-bin/python3',`#!${process.execPath}\nconst a=process.argv.slice(2);if(a[1]?.includes('importlib.metadata'))console.log('3.8.0');else if(a.includes('run')){console.log('done in 28ms (1 files mutated, 0 ignored, 0 unmodified)\\nStopping early, because we could not find any test case for any mutant.');process.exit(1);}else if(a.includes('pytest'))throw Error('unexpected baseline probe');else console.log('[]');`);fs.chmodSync(path.join(c.repo,'fake-bin/python3'),0o755);process.env.PATH=path.join(c.repo,'fake-bin');const rr=await m.register(c,'tests/test_pricing.py'),r=await m.runTarget(c,m.targetKey(rr.targets[0]));assert.equal(r.status,'error');assert.equal(r.agent_caused,true,r.error);assert.match(r.error,/no test in tests\/test_pricing\.py exercises pricing\.py/);assert.equal((await m.gate(c,{hook:true})).block,true);assert.equal((await m.gate(c,{hook:true})).block,false);});

test('hook trace records delivered banners and silent production edits',t=>{const {c}=fixture(t),cache=path.join(c.repo,'.cache');for(const exe of ['mutagate.mjs','mutagate-hook.cjs'])for(const event of ['SessionStart','PostToolUse'])spawnSync(process.execPath,[path.resolve(import.meta.dirname,'../scripts',exe),'hook',event],{input:JSON.stringify({cwd:c.repo,session_id:'s',tool_name:'Write',tool_input:{file_path:'src/main/java/acme/Foo.java'}}),env:{...process.env,CLAUDE_PLUGIN_DATA:cache,MUTAGATE_HARNESS:'claude',MUTAGATE_TRACE:'1'},encoding:'utf8'});const rows=fs.readFileSync(path.join(cache,'repos',m.hash(c.repo),'trace.jsonl'),'utf8').trim().split('\n').map(JSON.parse);assert.deepEqual(rows.map(r=>[r.event,r.delivered]),[['SessionStart',true],['PostToolUse',false],['SessionStart',true],['PostToolUse',false]]);});
